using System;using System.Runtime.InteropServices;using System.Runtime.InteropServices.ComTypes;using SolidWorks.Interop.sldworks;
public class SwRot{[DllImport("ole32.dll")]static extern int CreateBindCtx(uint reserved,out IBindCtx ctx);public static ISldWorks Connect(int pid){IBindCtx ctx;CreateBindCtx(0,out ctx);IRunningObjectTable rot;ctx.GetRunningObjectTable(out rot);IEnumMoniker en;rot.EnumRunning(out en);IMoniker[] ms=new IMoniker[1];while(en.Next(1,ms,IntPtr.Zero)==0){string name;try{ms[0].GetDisplayName(ctx,null,out name);}catch{continue;}if(name.TrimStart('!')=="SolidWorks_PID_"+pid){object obj;rot.GetObject(ms[0],out obj);return (ISldWorks)obj;}}return null;}}
